<?php require '../../config/database.php';require '../../includes/functions.php';require_admin();$rooms=$pdo->query("SELECT * FROM rooms ORDER BY id DESC")->fetchAll();$page_title='Manage Rooms';include '../../includes/header.php';?><div class="container page-hero"><div class="section-head"><div><h1>Rooms</h1><p class="muted">Maintain hotel room inventory.</p></div><a class="btn btn-primary" href="<?=url('admin/rooms/form.php')?>">+ Add room</a></div></div><section style="padding-top:5px"><div class="container"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Capacity</th><th>Rate</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rooms as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['room_type'])?></td><td><?=e($r['capacity'])?></td><td>₱<?=number_format($r['price_per_night'],2)?></td><td><?=e($r['status'])?></td><td class="actions"><a class="btn btn-outline btn-sm" href="<?=url('admin/rooms/form.php?id='.$r['id'])?>">Edit</a><form method="post" action="<?=url('admin/rooms/delete.php')?>" data-confirm="Delete this room? If bookings refer to it, deletion will be blocked and you should mark it as maintenance instead." data-confirm-title="Delete room" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger btn-sm" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include '../../includes/footer.php';?>